  "catalog.filters.weight.over3": "Plus de 3 Tons",
  "categories.info.1.title": "Configuré sur votre chantier",
  "attachments.category.drilling": "Forage",
  "attachments.category.handling": "Manutention",
  "attachments.category.demolition": "Démolition",
